insert into curricula (id,title,authority_note,term_structure) values ('ng-scheme-2025-preprimary-primary','Nigeria New Education Curriculum 2025 - Scheme of Work (Pre-Nursery to Primary 6)','Primary 1-6 described as NERDC-aligned; Pre-Nursery to Nursery 3 described as NAPPS-aligned (per source introduction).','13 weeks: wk1-4 teaching, wk5 mid-term assessment, wk6 mid-term break, wk7-10 teaching, wk11 revision, wk12 examination, wk13 closing (varies by subject).') on conflict (id) do nothing;
