insert into curriculum_topics values ('PN-health-habits-t1-w1','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'1',1,'teaching',null,'Introduction to Our Body','[]'::jsonb,'[]'::jsonb,'["Teacher uses songs and rhymes to introduce body parts", "Teacher points to and names body parts (head, hands, legs, face, body)", "Teacher uses charts and pictures to show the body", "Teacher guides pupils to touch and identify their own body parts", "Teacher shows pictures of clean, healthy children"]'::jsonb,'["Pupils sing body parts songs", "Pupils point to their body parts", "Pupils touch their body parts when named", "Pupils look at pictures of children", "Pupils say \"body\" with teacher"]'::jsonb,'["Charts", "Pictures", "Dolls", "Mirrors", "Body parts poster", "Video clips"]'::jsonb,10) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w2','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'2',2,'teaching',null,'Care of the Skin I - Bathing Regularly','[]'::jsonb,'[]'::jsonb,'["Teacher uses charts and video clips to explain bathing in simple terms", "Teacher demonstrates bathing using a doll with water, soap, and sponge", "Teacher sings bathing songs (\"This is the way we wash our body\")", "Teacher emphasizes bathing every day", "Teacher shows pictures of children taking baths"]'::jsonb,'["Pupils watch bathing demonstration", "Pupils sing bathing songs", "Pupils mime washing their body", "Pupils identify water, soap, and sponge", "Pupils practice with dolls"]'::jsonb,'["Doll", "Basin", "Water", "Soap", "Sponge", "Towel", "Charts", "Pictures", "Video clips"]'::jsonb,10) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w3','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'3',3,'teaching',null,'Care of the Skin II - Applying Body Cream','[]'::jsonb,'[]'::jsonb,'["Teacher demonstrates drying body with towel after bathing using a doll", "Teacher shows how to apply body cream and hair cream", "Teacher lets pupils touch and smell body cream", "Teacher emphasizes applying cream after bathing", "Teacher shows pictures of children applying cream"]'::jsonb,'["Pupils mime drying their body", "Pupils pretend to apply body cream", "Pupils touch body cream containers", "Pupils identify towel and cream", "Pupils practice on dolls"]'::jsonb,'["Towel", "Body cream", "Hair cream", "Lotion", "Charts", "Pictures", "Dolls", "Video clips"]'::jsonb,10) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w4','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'4',4,'teaching',null,'Care of the Skin III - Materials Used','[]'::jsonb,'[]'::jsonb,'["Teacher identifies and displays materials used for skin care (soap, sponge, towel, body cream, hair cream)", "Teacher names each material clearly and repeatedly", "Teacher demonstrates use of each material", "Teacher guides pupils to identify materials", "Teacher plays identification games with materials"]'::jsonb,'["Pupils identify materials used to take care of the skin", "Pupils point to each material when named", "Pupils touch and hold materials safely", "Pupils match materials to their uses", "Pupils participate in \"Find the...\" games"]'::jsonb,'["Soap", "Sponge", "Towel", "Body cream", "Hair cream", "Charts", "Pictures", "Sorting baskets"]'::jsonb,11) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w5','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'5',5,'midterm_assessment',null,'Midterm Examination','[]'::jsonb,'[]'::jsonb,'["Assessment through observation: Teacher observes pupils'' ability to identify body parts, skin care materials, and demonstrate simple bathing actions"]'::jsonb,'["Pupils demonstrate simple hygiene actions, identify materials, and participate in assessment activities"]'::jsonb,'["Assessment sheets", "All materials for demonstration"]'::jsonb,11) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w6','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'6',6,'midterm_break',null,'Midterm Break','[]'::jsonb,'[]'::jsonb,'["Rest and relaxation period"]'::jsonb,'["Rest and relaxation"]'::jsonb,'[]'::jsonb,11) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w7','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'7',7,'teaching',null,'Care of the Mouth and Teeth I - Introduction','[]'::jsonb,'[]'::jsonb,'["Teacher uses charts and large teeth model to introduce teeth and mouth", "Teacher lets pupils look at their teeth in mirrors", "Teacher sings teeth songs (\"Brush, brush, brush your teeth\")", "Teacher shows pictures of healthy teeth vs unhealthy teeth", "Teacher explains teeth help us eat food"]'::jsonb,'["Pupils point to their mouth and teeth", "Pupils look at teeth in mirrors", "Pupils sing teeth songs", "Pupils identify healthy teeth in pictures", "Pupils mime chewing food"]'::jsonb,'["Large teeth model", "Mirrors", "Charts", "Pictures", "Video clips", "Posters"]'::jsonb,11) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w8','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'8',8,'teaching',null,'Care of the Mouth and Teeth II - Brushing Twice Daily','[]'::jsonb,'[]'::jsonb,'["Teacher demonstrates brushing teeth using large teeth model and toothbrush", "Teacher emphasizes brushing in the morning and at night", "Teacher acts out morning and bedtime brushing routine", "Teacher uses pictures showing \"morning\" (sun) and \"night\" (moon)", "Teacher guides pupils to mime brushing"]'::jsonb,'["Pupils watch brushing demonstration", "Pupils identify morning and night pictures", "Pupils mime brushing teeth", "Pupils count \"one, two\" for twice daily", "Pupils sing brushing song with actions"]'::jsonb,'["Large teeth model", "Toothbrush", "Charts", "Sun/moon pictures", "Video clips", "Sequence cards"]'::jsonb,12) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w9','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'9',9,'teaching',null,'Care of the Mouth and Teeth III - Using Mouthwash','[]'::jsonb,'[]'::jsonb,'["Teacher shows mouthwash bottle and explains its use in very simple terms", "Teacher demonstrates rinsing mouth with water (mouthwash practice should be supervised by parents)", "Teacher shows pictures of clean mouth", "Teacher emphasizes asking parents for help with mouthwash", "Teacher practices rinsing and spitting actions"]'::jsonb,'["Pupils identify mouthwash bottle", "Pupils mime rinsing their mouth", "Pupils practice spitting actions (without liquid)", "Pupils understand to ask parents for help", "Pupils participate in mouth care routine"]'::jsonb,'["Mouthwash bottle (for display)", "Cup", "Water", "Charts", "Pictures", "Video clips"]'::jsonb,12) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w10','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'10',10,'teaching',null,'Care of the Mouth and Teeth IV - Materials Used','[]'::jsonb,'[]'::jsonb,'["Teacher identifies and displays all mouth care materials (toothbrush, toothpaste, mouthwash, cup)", "Teacher names each material clearly", "Teacher demonstrates complete mouth care routine", "Teacher guides pupils to identify each material", "Teacher plays matching games with materials"]'::jsonb,'["Pupils identify materials needed to take care of mouth and teeth", "Pupils point to materials when named", "Pupils demonstrate complete brushing routine", "Pupils match materials to pictures", "Pupils sort dental care items"]'::jsonb,'["Toothbrush", "Toothpaste", "Mouthwash", "Cup", "Charts", "Pictures", "Toy dental sets"]'::jsonb,13) on conflict (id) do nothing;
insert into curriculum_topics values ('PN-health-habits-t1-w11','ng-scheme-2025-preprimary-primary','PN','health-habits',1,'11',11,'revision',null,'Revision','[]'::jsonb,'[]'::jsonb,'["Teacher reviews all first term topics using songs, games, and demonstrations", "Reviews body parts, skin care (bathing, cream, materials), and mouth care (brushing, materials)"]'::jsonb,'["Pupils sing health songs, demonstrate bathing and brushing actions, identify all materials learned, participate in review games"]'::jsonb,'["All materials from weeks 1-10", "Charts", "Pictures", "Games"]'::jsonb,13) on conflict (id) do nothing;
