insert into curriculum_topics values ('N1-literacy-t1-w1','ng-scheme-2025-preprimary-primary','N1','literacy',1,'1',1,'teaching',null,'1.LISTENING AND SPEAKING SKILLS 2.READING SKILLS: Picture reading and recognition of objects around the home, school, and community. 3. WRITING SKILLS: Tracing, coloring, and writing of the alphabets Aa, Bb 4. SONGS, RHYMES AND POEMS: Singing traditional rhymes, songs, and poems.','[]'::jsonb,'[]'::jsonb,'["Listening & Speaking:", "The teacher engages pupils in simple conversations about their names, family, and school", "The teacher tells short, simple stories with picture aids", "The teacher asks pupils simple questions and encourages responses. Reading:", "The teacher displays pictures of objects in the home (bed, cup, spoon, chair)", "The teacher names objects and asks pupils to identify them", "The teacher uses picture flashcards for recognition activities. Writing:", "The teacher demonstrates proper sitting position and pencil grip", "The teacher writes uppercase and lowercase ''Aa'' on the board, showing starting points and direction", "The teacher writes ''Bb'' demonstrating straight lines and curves", "The teacher provides dotted letters for tracing practice", "The teacher guides pupils in coloring letter shapes. Songs/Rhymes:", "The teacher teaches \"Twinkle, Twinkle Little Star\"", "The teacher uses actions and gestures while singing", "The teacher encourages pupils to sing along"]'::jsonb,'["Listening & Speaking:", "Pupils listen attentively to the teacher''s stories", "Pupils respond to simple questions about themselves", "Pupils practice greeting words (Good morning, Hello). Reading:", "Pupils observe and identify pictures of home objects", "Pupils point to named objects in pictures", "Pupils name familiar objects they see. Writing:", "Pupils practice proper sitting and pencil holding", "Pupils trace dotted letters Aa and Bb", "Pupils color letter shapes Aa and Bb", "Pupils attempt to copy letters from the board. Songs/Rhymes:", "Pupils listen to the rhyme", "Pupils sing along with actions", "Pupils enjoy the musical activity"]'::jsonb,'["Picture charts", "Flashcards", "Writing book", "Pencils", "Crayons", "Erasers", "Alphabet chart", "Story book", "Audio player (optional)"]'::jsonb,136) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-literacy-t1-w2','ng-scheme-2025-preprimary-primary','N1','literacy',1,'2',2,'teaching',null,'1.LISTENING AND SPEAKING SKILLS 2.READING SKILLS: Picture reading and recognition of objects around the home, school, and community. 3. WRITING SKILLS: Tracing, coloring, and writing of the alphabets Aa, Bb, Cc 4. SONGS, RHYMES AND POEMS: Singing traditional rhymes, songs, and poems.','[]'::jsonb,'[]'::jsonb,'["Listening & Speaking:", "The teacher engages pupils in \"Show and Tell\" activities", "The teacher teaches positional words (in, on, under) through demonstration", "The teacher encourages pupils to describe what they see in pictures. Reading:", "The teacher shows pictures of school objects (bag, book, pencil, desk)", "The teacher helps pupils match objects to their pictures", "The teacher plays picture recognition games. Writing:", "The teacher reviews Aa and Bb", "The teacher introduces letter ''Cc'' with clear demonstration", "The teacher emphasizes the circular shape of C", "The teacher provides practice sheets for all three letters", "The teacher guides coloring activities for Aa, Bb, Cc. Songs/Rhymes:", "The teacher reviews \"Twinkle, Twinkle Little Star\"", "The teacher introduces \"Baa Baa Black Sheep\"", "The teacher encourages group singing"]'::jsonb,'["Listening & Speaking:", "Pupils participate in Show and Tell", "Pupils use positional words in simple sentences", "Pupils describe pictures using simple words. Reading:", "Pupils identify school objects in pictures", "Pupils match real objects to pictures", "Pupils name school objects around them. Writing:", "Pupils trace and copy Aa, Bb, Cc", "Pupils practice making circular shapes for C", "Pupils color all three letters beautifully", "Pupils recognize and name the letters. Songs/Rhymes:", "Pupils sing familiar rhymes confidently", "Pupils learn new rhyme with actions", "Pupils enjoy group singing activities"]'::jsonb,'["Picture charts", "Real objects", "Flashcards", "Writing book", "Pencils", "Crayons", "Coloring sheets", "Alphabet chart", "Song charts"]'::jsonb,137) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-literacy-t1-w3','ng-scheme-2025-preprimary-primary','N1','literacy',1,'3',3,'teaching',null,'1.LISTENING AND SPEAKING SKILLS 2.READING SKILLS: Picture reading and recognition of objects around the home, school, and community. 3. WRITING SKILLS: Tracing, coloring, and writing of the alphabets Aa, Bb, Cc 4. SONGS, RHYMES AND POEMS: Singing traditional rhymes, songs, and poems.','[]'::jsonb,'[]'::jsonb,'["Listening & Speaking:", "The teacher engages pupils in describing daily routines (morning, afternoon)", "The teacher uses puppets to demonstrate conversations", "The teacher teaches action words (run, jump, sit, stand). Reading:", "The teacher displays pictures of community helpers (teacher, doctor, police)", "The teacher talks about what each helper does", "The teacher asks pupils to identify helpers by their uniforms. Writing:", "The teacher conducts comprehensive practice of Aa, Bb, Cc", "The teacher emphasizes correct letter formation and starting points", "The teacher provides individual assistance where needed", "The teacher introduces coloring within boundaries", "The teacher uses letter recognition games. Songs/Rhymes:", "The teacher introduces \"Humpty Dumpty\"", "The teacher teaches hand gestures for the rhyme", "The teacher reviews all previously learned rhymes"]'::jsonb,'["Listening & Speaking:", "Pupils talk about their morning routines", "Pupils participate in puppet play conversations", "Pupils demonstrate action words physically. Reading:", "Pupils identify community helpers in pictures", "Pupils talk about helpers they know", "Pupils recognize helpers by uniforms. Writing:", "Pupils practice writing Aa, Bb, Cc confidently", "Pupils demonstrate improved letter formation", "Pupils color letters neatly within lines", "Pupils identify letters randomly shown. Songs/Rhymes:", "Pupils learn new rhyme with gestures", "Pupils sing all learned rhymes with enthusiasm", "Pupils perform rhymes with confidence"]'::jsonb,'["