insert into curriculum_topics values ('N1-numeracy-t3-w13','ng-scheme-2025-preprimary-primary','N1','numeracy',3,'13',13,'closing',null,'Closing, Promotion & Graduation Activities','[]'::jsonb,'[]'::jsonb,'["Year-End Closing:", "The teacher returns marked examination scripts with detailed feedback", "The teacher discusses individual year-long numeracy performance", "The teacher celebrates remarkable achievement of mastering 0-50!", "The teacher awards certificates and prizes for numeracy excellence", "The teacher distributes comprehensive end-of-year report cards", "The teacher provides recommendations for holiday practice", "The teacher prepares pupils for promotion to Nursery", "The teacher conducts numeracy graduation ceremony", "The teacher celebrates pupils'' journey from 0 to 50!", "The teacher thanks pupils and parents for wonderful year", "The teacher encourages continued numeracy practice during holidays"]'::jsonb,'["Year-End Closing:", "Pupils receive marked work and comprehensive report cards", "Pupils listen to year-long performance review", "Pupils celebrate counting from 0 to 50 proudly!", "Pupils receive certificates and awards for achievements", "Pupils get holiday practice materials", "Pupils prepare excitedly for promotion to Nursery", "Pupils participate in graduation ceremony", "Pupils showcase numeracy skills to parents", "Pupils celebrate their amazing number journey!", "Pupils say goodbye with confidence and numeracy pride", "Pupils look forward to continued learning in Nursery"]'::jsonb,'["Report cards", "Marked examination scripts", "Certificates", "Awards/medals", "Graduation materials", "Holiday practice workbooks", "Number charts", "0-50", "Celebration decorations", "Parent feedback forms", "\"I can count to", "50!\" badges"]'::jsonb,216) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w1','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'1',1,'teaching',null,'Living Things: Plants','["Meaning of plants", "Identification of plants", "Examples of plants (e.g., flowers, grass, trees)"]'::jsonb,'[]'::jsonb,'["Introduction to Plants:", "The teacher takes pupils on a nature walk around the school compound to observe plants", "The teacher explains that plants are living things that grow in soil and need water and sunlight", "The teacher shows real plants and pictures of different plants", "The teacher demonstrates how to touch plants gently. Identification Activities:", "The teacher points out different parts of plants (leaves, stem, roots, flowers)", "The teacher names various plants in the environment", "The teacher shows pictures and real samples of common plants. Examples:", "The teacher presents examples: flowers (rose, sunflower), grass, trees (mango tree, palm tree)", "The teacher uses picture cards to show variety of plants", "The teacher sings plant-related songs"]'::jsonb,'["Learning Activities:", "Pupils observe plants during nature walk", "Pupils listen and repeat \"plants are living things\"", "Pupils look at and touch real plants gently", "Pupils observe plant parts pointed out by teacher. Identification:", "Pupils point to plants around them", "Pupils name plants they see (with teacher''s help)", "Pupils identify plants in pictures. Examples:", "Pupils look at different plant examples", "Pupils match picture cards of plants", "Pupils sing plant songs with actions"]'::jsonb,'["Real plants (potted)", "Picture cards of plants", "Chart showing parts of plants", "Flowers", "Grass samples", "Leaves", "Song charts", "Nature walk area"]'::jsonb,218) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w2','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'2',2,'teaching',null,'Living Things: Plants (Continued)','["Growing plants", "Caring for plants", "Drawing and coloring plants"]'::jsonb,'[]'::jsonb,'["Plant Care:", "The teacher demonstrates how to water plants properly", "The teacher explains that plants need water, sunlight, and soil to grow", "The teacher shows pupils how to care for classroom plants", "The teacher discusses what happens when plants don''t get water (they die). Hands-on Activities:", "The teacher guides pupils in planting seeds in small pots or cups", "The teacher demonstrates gentle handling of plants", "The teacher organizes plant watering activities. Creative Activities:", "The teacher provides plant pictures for coloring", "The teacher guides pupils in drawing simple plants", "The teacher uses stickers and craft materials for plant activities"]'::jsonb,'["Plant Care:", "Pupils watch watering demonstration", "Pupils understand plants need water and sunlight", "Pupils help water classroom plants (with supervision)", "Pupils observe healthy and unhealthy plants. Hands-on:", "Pupils plant seeds in small containers", "Pupils handle plants gently", "Pupils take turns watering plants. Creative:", "Pupils color plant pictures", "Pupils draw simple plants (flowers, trees)", "Pupils create plant crafts with teacher''s guidance"]'::jsonb,'["Small pots/cups", "Soil", "Seeds (beans, maize)", "Watering can", "Real plants", "Coloring sheets", "Crayons", "Drawing paper", "Plant stickers", "Craft materials"]'::jsonb,219) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w3','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'3',3,'teaching',null,'Living Things: Fruits','["Meaning of fruits", "Identification of fruits", "Examples of fruits", "Fruits come from plants"]'::jsonb,'[]'::jsonb,'["Introduction to Fruits:", "The teacher explains that fruits are parts of plants that we can eat", "The teacher shows real fruits (apple, banana, orange, mango)", "The teacher allows pupils to touch, smell, and observe fruits", "The teacher explains that fruits come from plants/trees. Identification:", "The teacher displays various fruits and names each one", "The teacher describes fruits by color, shape, and size", "The teacher uses picture cards for fruit recognition", "The teacher cuts fruits to show inside (seeds, flesh). Activities:", "The teacher organizes fruit tasting activity (with permission)", "The teacher plays fruit identification games", "The teacher teaches fruit-related songs and rhymes"]'::jsonb,'["Learning:", "Pupils learn that fruits come from plants", "Pupils observe real fruits brought by teacher", "Pupils touch, smell, and feel different fruits", "Pupils understand fruits grow on plants. Identification:", "Pupils identify and name different fruits", "Pupils describe fruits (red apple, yellow banana)", "Pupils match fruit pictures", "Pupils observe cut fruits and seeds. Activities:", "Pupils taste different fruits (if permitted)", "Pupils play fruit games", "Pupils sing fruit songs enthusiastically"]'::jsonb,'["Real fruits (apple, banana, orange, mango, pineapple)", "Fruit pictures", "Flashcards", "Chart showing fruits", "Cutting board and knife (teacher use)", "Plates", "Fruit song charts", "Fruit models/toys"]'::jsonb,220) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w4','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'4',4,'teaching',null,'Animals','["Meaning of animals", "Description of animals", "Parts of animal bodies", "Similarities between animals and humans"]'::jsonb,'[]'::jsonb,'["Introduction to Animals:", "The teacher explains that animals are living things that can move from place to place", "The teacher shows pictures and toy animals", "The teacher describes different animals (dog, cat, goat, cow, bird, fish)", "The teacher makes animal sounds and encourages imitation. Body Parts:", "The teacher identifies animal body parts: head, eyes, ears, nose, mouth, legs, tail", "The teacher compares animal parts with human parts", "The teacher shows that both animals and humans have eyes, ears, nose, mouth", "The teacher discusses differences (tails, four legs vs two legs). Activities:", "The teacher plays animal movement games (hop like a rabbit, walk like a dog)", "The teacher uses videos or pictures showing animals", "The teacher sings animal songs"]'::jsonb,'["Learning:", "Pupils understand animals are living things", "Pupils observe animal pictures and toys", "Pupils listen to descriptions of animals", "Pupils make animal sounds (moo, bark, meow). Body Parts:", "Pupils identify animal body parts in pictures", "Pupils point to their own body parts (like animals)", "Pupils understand similarities: we both have eyes, ears, etc", "Pupils notice differences: animals have tails, four legs. Activities:", "Pupils imitate animal movements", "Pupils watch animal videos/pictures", "Pupils sing animal songs with actions"]'::jsonb,'["Animal pictures", "Toy animals", "Animal flashcards", "Chart showing animal body parts", "Videos of animals (optional)", "Animal masks", "Song charts", "Story books about animals"]'::jsonb,221) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w5','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'5',5,'midterm_assessment',null,'Mid-term Assessment/test','[]'::jsonb,'[]'::jsonb,'["Assessment Activities:", "The teacher administers comprehensive pre-science assessment", "The teacher tests knowledge of plants (identification, parts)", "The teacher assesses fruit recognition and naming", "The teacher tests animal identification and sounds", "The teacher evaluates understanding of body parts (animals and humans)", "The teacher uses oral questions, picture identification, and practical tasks", "The teacher observes pupils'' responses and participation", "The teacher records individual performance and identifies areas needing support"]'::jsonb,'["Assessment Tasks:", "Pupils identify plants in pictures and real samples", "Pupils name parts of plants shown", "Pupils identify and name fruits presented", "Pupils identify animals in pictures", "Pupils make animal sounds when asked", "Pupils point to animal body parts", "Pupils identify their own body parts", "Pupils demonstrate understanding of topics covered"]'::jsonb,'["Assessment sheets", "Plant samples", "Fruit pictures", "Animal pictures", "Body parts chart", "Real objects", "Mark book", "Assessment checklist"]'::jsonb,222) on conflict (id) do nothing;
