insert into curriculum_topics values ('N1-pre-science-t1-w7','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'7',7,'teaching',null,'Domestic Animals','["Meaning of domestic animals", "Examples of domestic animals", "Where domestic animals live", "Caring for domestic animals"]'::jsonb,'[]'::jsonb,'["Introduction:", "The teacher explains that domestic animals are animals we keep at home", "The teacher lists examples: dog, cat, rabbit, chicken, goat, sheep, cow", "The teacher shows pictures of domestic animals", "The teacher discusses why we keep these animals at home (pets, food, help). Homes of Animals:", "The teacher shows where domestic animals live (kennel for dogs, coop for chickens)", "The teacher discusses how we care for domestic animals (feeding, cleaning, shelter)", "The teacher demonstrates responsible animal care. Activities:", "The teacher organizes visit to see domestic animals (if possible)", "The teacher plays domestic animal identification games", "The teacher teaches songs about domestic animals"]'::jsonb,'["Learning:", "Pupils understand domestic animals live with us", "Pupils name domestic animals: dog, cat, chicken, goat", "Pupils observe pictures of domestic animals", "Pupils learn we keep them for various reasons. Animal Homes:", "Pupils identify where animals live (kennel, coop)", "Pupils understand animals need food and care", "Pupils learn to treat animals kindly. Activities:", "Pupils observe domestic animals (if available)", "Pupils play animal identification games", "Pupils sing songs about domestic animals with enthusiasm"]'::jsonb,'["Pictures of domestic animals", "Toy domestic animals", "Pictures of animal homes", "Flashcards", "Chart showing domestic animals", "Song charts", "Story books", "Videos (optional)"]'::jsonb,223) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w8','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'8',8,'teaching',null,'Parts of the Body: the Head','["Identification of the head", "Parts on the head", "Uses of the head"]'::jsonb,'[]'::jsonb,'["Introduction to the Head:", "The teacher points to their own head and asks pupils to touch theirs", "The teacher explains the head is the top part of our body", "The teacher shows pictures and charts of the head", "The teacher names parts found on the head: hair, forehead, eyes, ears, nose, mouth, chin. Parts on the Head:", "The teacher identifies each part on their own head", "The teacher asks pupils to point to each part on their own heads", "The teacher uses a large diagram showing parts of the head", "The teacher plays \"Simon Says\" touching head parts. Uses of the Head:", "The teacher explains: the head holds our brain (for thinking), face (for seeing, smelling, eating, hearing)", "The teacher demonstrates nodding (yes) and shaking head (no)", "The teacher discusses protecting our heads (wearing helmets)"]'::jsonb,'["Learning:", "Pupils touch their own heads", "Pupils understand the head is on top of the body", "Pupils observe head pictures and charts", "Pupils identify parts on the head. Parts Identification:", "Pupils point to their hair, eyes, ears, nose, mouth", "Pupils touch each part when named by teacher", "Pupils observe large head diagram", "Pupils play \"Simon Says\" game with head parts. Uses:", "Pupils understand the head helps us think, see, hear, smell, eat", "Pupils practice nodding and shaking head", "Pupils learn to protect their heads"]'::jsonb,'["Large body chart", "Head diagram", "Mirror", "Pictures of heads", "Flashcards", "Helmet (for demonstration)", "Simon Says game materials"]'::jsonb,224) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w9','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'9',9,'teaching',null,'Parts of the Body: Mouth and Teeth','["Identification of the mouth", "Identification of the teeth", "Uses of mouth and teeth", "Care of mouth and teeth"]'::jsonb,'[]'::jsonb,'["The Mouth:", "The teacher points to their mouth and asks pupils to point to theirs", "The teacher shows pictures of mouths", "The teacher opens mouth to show inside: teeth, tongue, gums", "The teacher uses a mirror so pupils can see their own mouths. The Teeth:", "The teacher identifies teeth inside the mouth", "The teacher explains teeth help us chew food", "The teacher shows picture of healthy teeth", "The teacher discusses baby teeth and adult teeth (simply). Uses and Care:", "The teacher explains: mouth is for eating, talking, singing, drinking", "The teacher explains: teeth are for biting and chewing food", "The teacher demonstrates proper tooth brushing", "The teacher emphasizes brushing teeth twice daily", "The teacher discusses healthy foods for strong teeth"]'::jsonb,'["The Mouth:", "Pupils point to their mouths", "Pupils observe mouth pictures", "Pupils open their mouths to see teeth and tongue", "Pupils look at their mouths in mirrors. The Teeth:", "Pupils identify their teeth", "Pupils understand teeth help us chew", "Pupils observe pictures of teeth", "Pupils count some of their teeth (with help). Uses and Care:", "Pupils understand mouth is for eating and talking", "Pupils understand teeth help us chew food", "Pupils watch tooth brushing demonstration", "Pupils practice brushing motion", "Pupils learn to brush teeth daily"]'::jsonb,'["Mirrors", "Pictures of mouth and teeth", "Toothbrush and toothpaste", "Dental chart", "Flashcards", "Healthy food pictures", "Tooth brushing song chart"]'::jsonb,225) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w10','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'10',10,'teaching',null,'Parts of the Body: Lips and Tongue','["Identification of lips", "Identification of tongue", "Uses of lips and tongue", "Importance of these organs"]'::jsonb,'[]'::jsonb,'["The Lips:", "The teacher points to their lips and asks pupils to touch theirs", "The teacher explains lips are the outer part of the mouth", "The teacher shows that lips can move (smiling, pouting, talking)", "The teacher uses pictures showing lips. The Tongue:", "The teacher sticks out tongue and asks pupils to see theirs in mirror", "The teacher explains the tongue is inside the mouth", "The teacher shows pictures of the tongue", "The teacher demonstrates tongue movements. Uses:", "The teacher explains: lips help us talk, eat, drink, whistle, kiss, smile", "The teacher explains: tongue helps us taste food, talk, swallow, lick", "The teacher discusses how we taste different flavors (sweet, sour, bitter, salty)", "The teacher conducts simple tasting activity (if permitted)", "The teacher emphasizes keeping lips and tongue clean"]'::jsonb,'["The Lips:", "Pupils touch their lips", "Pupils understand lips are outside the mouth", "Pupils move their lips (smile, pout)", "Pupils observe lip pictures. The Tongue:", "Pupils stick out their tongues safely", "Pupils see their tongues in mirrors", "Pupils observe tongue pictures", "Pupils move their tongues around. Uses:", "Pupils understand lips help us talk and eat", "Pupils understand tongue helps us taste food", "Pupils learn about different tastes", "Pupils taste safe foods (if permitted)", "Pupils learn to keep mouth parts clean"]'::jsonb,'["Mirrors", "Pictures of lips and tongue", "Body parts chart", "Safe tasting samples (sugar-sweet, lemon-sour)", "Flashcards", "Song charts about body parts"]'::jsonb,226) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w11','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'11',11,'revision',null,'Revision of First Term Work All Topics Covered','[]'::jsonb,'[]'::jsonb,'["Comprehensive Revision:", "The teacher systematically reviews living things: plants (identification, parts, care)", "The teacher revises fruits (identification, examples, where they come from)", "The teacher reviews animals (meaning, body parts, similarities with humans)", "The teacher revises domestic animals (examples, where they live, care)", "The teacher reviews parts of the body: head, mouth, teeth, lips, tongue", "The teacher revises uses of each body part", "The teacher uses games, songs, and interactive activities for revision", "The teacher conducts mock examination activities", "The teacher identifies areas where pupils need extra support", "The teacher builds confidence for final examination"]'::jsonb,'["Revision Activities:", "Pupils identify plants and their parts", "Pupils name and identify various fruits", "Pupils identify animals and their body parts", "Pupils name domestic animals and their uses", "Pupils identify all body parts learned: head, mouth, teeth, lips, tongue", "Pupils explain uses of body parts (with help)", "Pupils participate in revision games and songs", "Pupils complete mock test activities", "Pupils ask questions about difficult areas", "Pupils prepare confidently for examination"]'::jsonb,'["All term''s materials", "Plant samples", "Fruit pictures", "Animal pictures", "Body parts charts", "Revision worksheets", "Mock test materials", "Games", "Song charts"]'::jsonb,228) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w12','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'12',12,'examination',null,'End of Term Examination','[]'::jsonb,'[]'::jsonb,'["Examination Administration:", "The teacher administers comprehensive end-of-term examination", "The teacher tests plant identification and knowledge", "The teacher assesses fruit recognition and naming", "The teacher tests animal knowledge (identification, sounds, body parts)", "The teacher assesses domestic animal knowledge", "The teacher tests body parts identification (head, mouth, teeth, lips, tongue)", "The teacher evaluates understanding of uses of body parts", "The teacher uses oral questions, picture identification, and practical demonstrations", "The teacher marks examination and records scores", "The teacher prepares report cards with comments"]'::jsonb,'["Examination Tasks:", "Pupils identify plants in pictures and real samples", "Pupils name fruits shown in pictures", "Pupils identify animals and make appropriate sounds", "Pupils name domestic animals", "Pupils point to and name body parts: head, mouth, teeth, lips, tongue", "Pupils explain uses of body parts (simply)", "Pupils answer oral questions from teacher", "Pupils demonstrate practical knowledge", "Pupils complete all examination tasks", "Pupils show understanding of first term topics"]'::jsonb,'["Examination materials", "Plant pictures", "Fruit pictures", "Animal pictures", "Body parts chart", "Real samples", "Assessment sheets", "Mark book", "Report cards"]'::jsonb,229) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t1-w13','ng-scheme-2025-preprimary-primary','N1','pre-science',1,'13',13,'closing',null,'Closing & End of Term Activities','[]'::jsonb,'[]'::jsonb,'["Closing Activities:", "The teacher returns marked examination scripts", "The teacher discusses individual performance with pupils", "The teacher celebrates pupils'' science learning achievements", "The teacher awards certificates/stickers for good performance", "The teacher distributes report cards", "The teacher provides holiday tips (observing plants, animals at home)", "The teacher gives preview of second term topics", "The teacher encourages continued observation of nature", "The teacher thanks pupils for active participation"]'::jsonb,'["Closing Activities:", "Pupils receive marked work and report cards", "Pupils listen to teacher''s feedback", "Pupils celebrate their science learning", "Pupils receive awards and recognition", "Pupils get holiday observation tasks", "Pupils look forward to second term", "Pupils say goodbye to classmates and teacher"]'::jsonb,'["Report cards", "Marked scripts", "Certificates", "Awards/stickers", "Holiday observation sheets", "Celebration materials"]'::jsonb,230) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w1','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'1',1,'teaching',null,'THE FIVE SENSES: Introduction','["What are senses?", "The five senses overview", "Sense organs introduction"]'::jsonb,'[]'::jsonb,'["Introduction to Senses:", "The teacher welcomes pupils back and reviews first term briefly", "The teacher explains that senses help us know about things around us", "The teacher introduces the five senses: sight, hearing, smell, taste, touch", "The teacher shows pictures of the five sense organs. Sense Organs:", "The teacher names sense organs: eyes (seeing), ears (hearing), nose (smelling), tongue (tasting), skin (touching)", "The teacher asks pupils to point to each organ on their bodies", "The teacher explains each sense helps us in different ways. Activities:", "The teacher sings \"Five Senses Song\"", "The teacher plays identification games with senses", "The teacher uses charts showing the five senses"]'::jsonb,'["Learning:", "Pupils understand senses help us know things", "Pupils learn there are five senses", "Pupils observe pictures of sense organs. Identification:", "Pupils point to their eyes, ears, nose, tongue, and touch their skin", "Pupils name sense organs with teacher", "Pupils understand each sense does something different. Activities:", "Pupils sing five senses song", "Pupils participate in sense games", "Pupils observe and discuss sense charts"]'::jsonb,'["Five senses chart", "Pictures of sense organs", "Body diagram", "Flashcards", "Song charts", "Story books about senses"]'::jsonb,231) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w2','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'2',2,'teaching',null,'The Sense of Sight: Eyes','["The eyes as organs of sight", "Uses of eyes", "Caring for our eyes"]'::jsonb,'[]'::jsonb,'["The Eyes:", "The teacher explains eyes help us see things around us", "The teacher asks pupils to point to their eyes", "The teacher shows pictures of eyes and explains parts (eyelids, eyelashes, eyebrows)", "The teacher uses mirrors so pupils can see their own eyes. Uses of Eyes:", "The teacher explains: eyes help us see colors, shapes, people, things, words, pictures", "The teacher demonstrates looking at various objects", "The teacher plays \"I Spy\" game using sight", "The teacher discusses what happens when we close our eyes (can''t see). Eye Care:", "The teacher teaches: don''t rub eyes with dirty hands, don''t look at bright sun, visit eye doctor, eat healthy foods (carrots), rest eyes when tired", "The teacher demonstrates proper face washing including eyes", "The teacher discusses wearing glasses if needed"]'::jsonb,'["The Eyes:", "Pupils understand eyes help us see", "Pupils point to their eyes", "Pupils observe eye pictures", "Pupils look at their eyes in mirrors. Uses:", "Pupils understand eyes help us see everything around us", "Pupils look at objects teacher points out", "Pupils play \"I Spy\" using their sight", "Pupils experience closing eyes and not seeing. Care:", "Pupils learn to keep hands away from eyes", "Pupils learn not to look at bright sun", "Pupils understand importance of eye health", "Pupils learn about healthy foods for eyes"]'::jsonb,'["Mirrors", "Eye pictures and charts", "Various colorful objects", "Pictures of healthy foods", "Glasses (for demonstration)", "I Spy game materials", "Eye care posters"]'::jsonb,232) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w3','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'3',3,'teaching',null,'The Sense of Hearing: Ears & the Sense of Smell: Nose','["Ears as organs of hearing", "Nose as organ of smell", "Uses and care"]'::jsonb,'[]'::jsonb,'["The Ears:", "The teacher explains ears help us hear sounds", "The teacher asks pupils to touch their ears", "The teacher makes different sounds (clapping, bell, whistle) for pupils to hear", "The teacher shows pictures of ears. Uses and Care of Ears:", "The teacher explains: ears help us hear voices, music, warnings, animals, nature sounds", "The teacher teaches: don''t put things in ears, keep ears clean, protect from loud noise", "The teacher plays listening games. The Nose:", "The teacher explains nose helps us smell things", "The teacher asks pupils to touch their noses", "The teacher presents items with different smells (perfume, orange, soap)", "The teacher guides safe smelling activities. Uses and Care:", "The teacher explains: nose helps us smell good and bad things, helps us breathe", "The teacher teaches: blow nose gently with tissue, keep nose clean", "The teacher plays smell identification games (if safe)"]'::jsonb,'["The Ears:", "Pupils understand ears help us hear", "Pupils touch their ears", "Pupils listen to different sounds made by teacher", "Pupils observe ear pictures. Care:", "Pupils understand ears help us hear many things", "Pupils learn to keep ears safe and clean", "Pupils play listening games. The Nose:", "Pupils understand nose helps us smell", "Pupils touch their noses", "Pupils smell different safe items", "Pupils practice safe smelling. Care:", "Pupils understand nose helps us breathe and smell", "Pupils learn to keep nose clean", "Pupils identify smells in games"]'::jsonb,'["Pictures of ears and nose", "Sound-making objects (bell, drum, whistle)", "Safe smelling items (perfume, orange, flower, soap)", "Tissues", "Body charts", "Listening game materials"]'::jsonb,233) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w4','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'4',4,'teaching',null,'The Sense of Touch: Skin & the Sense of Taste: Tongue','["Skin as organ of touch", "Tongue as organ of taste", "Uses and care"]'::jsonb,'[]'::jsonb,'["The Skin (Touch):", "The teacher explains skin covers our whole body and helps us feel", "The teacher asks pupils to touch their skin (arms, face, hands)", "The teacher presents objects with different textures (soft, hard, rough, smooth, hot, cold)", "The teacher guides touching activities safely. Uses and Care:", "The teacher explains: skin helps us feel things, protects our body, shows when something is hot or sharp", "The teacher teaches: keep skin clean (bathing), use lotion, protect from sun, cover wounds. The Tongue (Taste):", "The teacher reviews tongue from first term", "The teacher explains tongue helps us taste flavors", "The teacher introduces four basic tastes: sweet, sour, salty, bitter", "The teacher provides safe tasting samples (if permitted). Uses and Care:", "The teacher explains: tongue helps us taste food, talk, swallow", "The teacher teaches: keep mouth clean, brush teeth, don''t eat dirty things"]'::jsonb,'["The Skin:", "Pupils understand skin helps us feel", "Pupils touch their skin on different body parts", "Pupils touch objects with different textures", "Pupils identify soft, hard, rough, smooth objects. Care:", "Pupils understand skin protects us and helps us feel", "Pupils learn to keep skin clean and safe", "Pupils understand importance of bathing. The Tongue:", "Pupils recall tongue from first term", "Pupils understand tongue helps us taste", "Pupils learn about sweet, sour, salty, bitter", "Pupils taste safe foods (if permitted). Care:", "Pupils understand multiple uses of tongue", "Pupils learn to keep mouth and tongue clean"]'::jsonb,'["Different textured objects (cotton, sandpaper, stone, fabric)", "Body diagram", "Safe tasting samples (if permitted)", "Soap and water", "Lotion", "Pictures of skin care", "Taste flashcards"]'::jsonb,234) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w5','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'5',5,'midterm_assessment',null,'Mid-term Assessment/tes T','[]'::jsonb,'[]'::jsonb,'["Assessment Activities:", "The teacher administers mid-term assessment on the five senses", "The teacher tests identification of sense organs (eyes, ears, nose, tongue, skin)", "The teacher assesses understanding of what each sense does", "The teacher tests matching senses to their uses", "The teacher evaluates knowledge of sense organ care", "The teacher uses oral questions and practical demonstrations", "The teacher assesses through games (listening, smelling, touching, seeing activities)", "The teacher records pupils'' performance"]'::jsonb,'["Assessment Tasks:", "Pupils identify all five sense organs on their bodies", "Pupils name what each sense organ does (eyes-see, ears-hear, nose-smell, tongue-taste, skin-touch)", "Pupils match senses to activities", "Pupils demonstrate understanding of sense organ care", "Pupils participate in practical sense activities", "Pupils answer oral questions from teacher", "Pupils show understanding of five senses topics"]'::jsonb,'["Assessment sheets", "Five senses chart", "Sound objects", "Smelling items", "Textured objects", "Flashcards", "Mark book", "Assessment checklist"]'::jsonb,235) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w6','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,236) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w7','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'7',7,'teaching',null,'AIR','["Description of air", "Air is invisible but can be felt", "Air occupies space", "Air is everywhere"]'::jsonb,'[]'::jsonb,'["Introduction to Air:", "The teacher explains that air is all around us but we cannot see it", "The teacher demonstrates feeling air by waving hand in front of face", "The teacher uses a fan to show moving air", "The teacher explains air is invisible but real. Properties of Air:", "The teacher demonstrates air takes up space using balloon experiment", "The teacher blows up a balloon to show air filling space", "The teacher shows empty bottle is actually full of air", "The teacher explains air is everywhere: in room, outside, in balloons, in tires. Feeling Air:", "The teacher conducts activities where pupils feel air (blowing, fanning)", "The teacher takes pupils outside to feel wind (moving air)", "The teacher demonstrates breathing in and out (air going in our bodies)", "The teacher makes air visible using bubbles or smoke (with supervision)"]'::jsonb,'["Learning:", "Pupils understand air is around us but invisible", "Pupils wave hands to feel air movement", "Pupils feel air from fan", "Pupils understand we can''t see air but it''s real. Air Properties:", "Pupils observe balloon being inflated with air", "Pupils see air takes up space in balloon", "Pupils learn \"empty\" bottle has air", "Pupils understand air is everywhere. Feeling Air:", "Pupils blow on their hands to feel air", "Pupils go outside to feel wind", "Pupils breathe in and out, feeling air", "Pupils observe bubbles showing air movement"]'::jsonb,'["Balloons", "Fan", "Empty plastic bottle", "Bubble solution and wand", "Pictures showing air", "Chart about air", "Outdoor space for wind observation"]'::jsonb,236) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w8','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'8',8,'teaching',null,'Uses of Air','["Breathing (most important use)", "Cooling", "Filling balloons and tires", "Drying clothes"]'::jsonb,'[]'::jsonb,'["Uses of Air:", "The teacher explains the most important use: breathing (we need air to live)", "The teacher demonstrates breathing in and out", "The teacher explains we breathe air all the time, even when sleeping", "The teacher discusses that all living things need air. Other Uses:", "The teacher explains air helps cool us (fanning, air conditioning, wind)", "The teacher demonstrates using hand fan for cooling", "The teacher shows air fills balloons, tires, balls, swimming floats", "The teacher explains air helps dry wet clothes on the line", "The teacher shows pictures of wind blowing clothes dry. Activities:", "The teacher inflates balloons with pupils", "The teacher demonstrates fanning motion for cooling", "The teacher discusses importance of fresh air"]'::jsonb,'["Learning:", "Pupils understand breathing air keeps us alive", "Pupils practice breathing in and out", "Pupils understand we need air every moment", "Pupils learn all living things need air. Other Uses:", "Pupils understand air helps cool us down", "Pupils fan themselves and feel cooling", "Pupils see balloons filled with air", "Pupils understand air dries wet clothes", "Pupils observe pictures of air drying things. Activities:", "Pupils help blow up balloons (with assistance)", "Pupils practice fanning for cooling", "Pupils breathe fresh air outside"]'::jsonb,'["Balloons", "Hand fans", "Pictures of tires, balls", "Pictures of clothes drying", "Air conditioning/fa n for demonstration", "Chart showing uses of air"]'::jsonb,237) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w9','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'9',9,'teaching',null,'Air Transportatio N','["Air as means of transportation", "Vehicles that move through air", "Examples: airplane, helicopter, kite, hot air balloon", "Smell travels through air"]'::jsonb,'[]'::jsonb,'["Air Transportation:", "The teacher explains some vehicles move through the air (not on ground or water)", "The teacher shows pictures of airplanes, helicopters, hot air balloons, kites", "The teacher explains airplanes carry people and goods through the sky", "The teacher shows videos or pictures of air travel. Types of Air Transport:", "The teacher describes airplane: big, has wings, carries many people, flies high", "The teacher describes helicopter: has spinning blades on top, can hover", "The teacher describes hot air balloon: big balloon with basket, floats in air", "The teacher explains kites: toys that fly in the wind. Smell in Air:", "The teacher explains smells travel through air to our noses", "The teacher demonstrates with perfume or cooking smell traveling", "The teacher discusses how we smell things from far away because smell moves in air"]'::jsonb,'["Learning:", "Pupils understand some things move through air", "Pupils observe pictures of air vehicles", "Pupils learn airplanes fly in the sky", "Pupils watch videos of air transport. Types:", "Pupils identify airplanes in pictures", "Pupils recognize helicopters", "Pupils observe hot air balloons", "Pupils understand kites fly with wind", "Pupils make airplane sounds and movements. Smell:", "Pupils understand smells move through air", "Pupils smell things from across the room", "Pupils learn about air carrying smells"]'::jsonb,'["Pictures of airplanes, helicopters, hot air balloons, kites", "Toy planes", "Videos of air transportation", "Paper to make paper airplanes", "Perfume for smell demonstration", "Chart showing air transport"]'::jsonb,238) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w10','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'10',10,'teaching',null,'Water','["Description of water", "Properties of water", "Clean and dirty water", "Importance of clean water"]'::jsonb,'[]'::jsonb,'["Introduction to Water:", "The teacher shows water in a clear container", "The teacher explains water is a liquid we can see and feel", "The teacher discusses properties: water is clear (transparent), has no color when clean, can pour, takes shape of container", "The teacher lets pupils touch water safely. Clean vs Dirty Water:", "The teacher shows samples of clean water and dirty water", "The teacher explains clean water is clear, safe to drink", "The teacher shows dirty water has dirt, is not clear, not safe to drink", "The teacher emphasizes drinking only clean water", "The teacher discusses where we get clean water (tap, filtered, bottled). Importance:", "The teacher explains we need clean water to stay healthy", "The teacher discusses dangers of dirty water (sickness)", "The teacher emphasizes keeping water containers clean", "The teacher teaches not to play in dirty water"]'::jsonb,'["Learning:", "Pupils observe water in container", "Pupils understand water is a liquid", "Pupils learn water is clear when clean, pours, takes shape of container", "Pupils touch water safely. Clean vs Dirty:", "Pupils observe samples of clean and dirty water", "Pupils identify clean water as clear and safe", "Pupils recognize dirty water is not safe", "Pupils learn to drink only clean water", "Pupils identify sources of clean water. Importance:", "Pupils understand importance of clean water for health", "Pupils learn dirty water makes us sick", "Pupils learn to keep drinking water clean", "Pupils avoid dirty water"]'::jsonb,'["Clear containers", "Clean water samples", "Dirty water samples", "Pictures of water sources", "Drinking water", "Chart showing clean vs dirty water", "Water bottles"]'::jsonb,240) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w11','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'11',11,'teaching',null,'Sources of Water & Uses of Water','["Sources: rain, tap, well, stream, river", "Uses: drinking, cooking, bathing, washing, cleaning", "Objects that float and sink"]'::jsonb,'[]'::jsonb,'["Sources of Water:", "The teacher explains where water comes from: rain from sky, tap in homes, wells, streams, rivers, ocean", "The teacher shows pictures of different water sources", "The teacher discusses which sources give us drinking water (tap, well, filtered rain)", "The teacher explains rain is important source of water. Uses of Water:", "The teacher lists uses: drinking (most important), cooking food, bathing, washing hands/clothes/dishes , cleaning house, watering plants, for animals", "The teacher shows pictures of each use", "The teacher emphasizes not wasting water", "The teacher discusses turning off taps when not using water. Float and Sink:", "The teacher conducts water experiment with objects", "The teacher explains some things float (stay on top of water), some sink (go down in water)", "The teacher demonstrates with objects: wood floats, stone sinks, plastic bottle floats, metal spoon sinks, leaf floats", "The teacher lets pupils predict and observe"]'::jsonb,'["Sources:", "Pupils learn water comes from rain, tap, well, river", "Pupils observe pictures of water sources", "Pupils identify safe drinking water sources", "Pupils understand rain gives us water. Uses:", "Pupils learn many uses of water: drinking, cooking, bathing, washing, cleaning, watering plants", "Pupils observe pictures of water uses", "Pupils understand importance of not wasting water", "Pupils learn to turn off taps. Float and Sink:", "Pupils observe water experiment", "Pupils learn some things float, some sink", "Pupils watch objects floating and sinking", "Pupils predict what will float or sink", "Pupils enjoy hands-on water activity"]'::jsonb,'["Pictures of water sources", "Pictures of water uses", "Large water container/basin", "Objects for experiment (wood, stone, plastic, metal spoon, leaf, cork, key)", "Towels", "Chart showing uses of water"]'::jsonb,241) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w12','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'12',12,'revision',null,'Revision & End of Term Examination','[]'::jsonb,'[]'::jsonb,'["Examination Administration:", "The teacher administers comprehensive end-of-term examination", "The teacher tests knowledge of five senses (identification, uses, care)", "The teacher assesses understanding of air (properties, uses, transportation)", "The teacher tests water knowledge (clean vs dirty, sources, uses)", "The teacher evaluates understanding of floating and sinking", "The teacher uses oral questions, picture identification, and practical tasks", "The teacher conducts practical demonstrations (identifying senses, float/sink activity)", "The teacher marks examination and prepares report cards"]'::jsonb,'["Examination Tasks:", "Pupils identify all five sense organs and their uses", "Pupils explain how to care for sense organs", "Pupils answer questions about air and its uses", "Pupils identify air transportation vehicles", "Pupils distinguish clean from dirty water", "Pupils name sources and uses of water", "Pupils identify which objects float or sink", "Pupils answer oral questions", "Pupils participate in practical demonstrations", "Pupils show understanding of second term topics"]'::jsonb,'["Examination papers", "Five senses pictures", "Air and water pictures", "Float/sink objects", "Clean/dirty water samples", "Assessment sheets", "Mark book", "Report cards"]'::jsonb,242) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t2-w13','ng-scheme-2025-preprimary-primary','N1','pre-science',2,'13',13,'closing',null,'Closing & End of Term Activities','[]'::jsonb,'[]'::jsonb,'["Closing Activities:", "The teacher returns marked scripts with feedback", "The teacher discusses individual performance", "The teacher celebrates science achievements", "The teacher awards certificates for excellence", "The teacher distributes report cards", "The teacher provides holiday activities (observe senses, air, water at home)", "The teacher previews third term topics", "The teacher encourages continued science curiosity"]'::jsonb,'["Closing Activities:", "Pupils receive marked work and report cards", "Pupils listen to feedback", "Pupils celebrate their science learning", "Pupils receive awards", "Pupils get holiday activities", "Pupils look forward to third term", "Pupils say goodbye happily"]'::jsonb,'["Report cards", "Marked scripts", "Certificates", "Awards", "Holiday activity sheets", "Celebration materials"]'::jsonb,243) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w1','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'1',1,'teaching',null,'Simple Machines','["Definition of simple machines", "Introduction to machines", "Machines help us do work"]'::jsonb,'[]'::jsonb,'["Introduction:", "The teacher welcomes pupils back and reviews previous terms briefly", "The teacher explains machines are things that help us do work easily", "The teacher explains simple machines are basic tools that make work easier", "The teacher shows examples of simple machines in the classroom and environment. Understanding Machines:", "The teacher demonstrates how machines help us: scissors help us cut, broom helps us sweep, wheelbarrow helps us carry", "The teacher shows that without machines, work would be harder", "The teacher introduces simple machines: lever, wheel, inclined plane (simple concepts). Activities:", "The teacher shows real simple machines or pictures", "The teacher demonstrates using simple tools", "The teacher plays games identifying machines"]'::jsonb,'["Learning:", "Pupils understand machines help us work", "Pupils learn simple machines make work easy", "Pupils observe examples of machines. Understanding:", "Pupils see how scissors cut, brooms sweep, wheelbarrows carry", "Pupils understand machines make work easier", "Pupils learn about simple machines. Activities:", "Pupils observe real machines and pictures", "Pupils watch demonstrations of tools", "Pupils identify machines in games"]'::jsonb,'["Pictures of simple machines", "Real tools (scissors, broom, rake)", "Toy wheelbarrow", "Simple machine chart", "Flashcards"]'::jsonb,245) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w2','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'2',2,'teaching',null,'Simple Machines (Continued)','["Identification of simple machines", "Examples: scissors, broom, knife, spoon, wheelbarrow, door handle", "Uses of simple machines"]'::jsonb,'[]'::jsonb,'["Identification:", "The teacher shows various simple machines one by one", "The teacher names each: scissors (for cutting), knife (for cutting), spoon (for eating/scooping), broom (for sweeping), rake (for gathering), wheelbarrow (for carrying), door handle (for opening), bottle opener", "The teacher lets pupils handle safe simple machines", "The teacher shows pictures of machines we use at home and school. Uses:", "The teacher demonstrates use of each machine: cutting paper with scissors, sweeping with broom, etc", "The teacher explains how each machine makes specific work easier", "The teacher discusses safety when using machines (especially sharp ones)", "The teacher emphasizes machines are tools that help us, not toys. Activities:", "The teacher organizes safe hands-on activities (sweeping, scooping with spoon)", "The teacher plays matching games (machine to its use)", "The teacher sings songs about tools and machines"]'::jsonb,'["Identification:", "Pupils observe various simple machines", "Pupils name machines with teacher: scissors, knife, spoon, broom, rake, wheelbarrow", "Pupils handle safe machines carefully", "Pupils recognize machines in pictures. Uses:", "Pupils watch demonstrations of each machine", "Pupils learn what work each machine does", "Pupils understand safety with machines", "Pupils learn machines are tools, not toys. Activities:", "Pupils practice using safe machines (sweeping, scooping)", "Pupils match machines to their uses", "Pupils sing songs about tools"]'::jsonb,'["Real simple machines (scissors, broom, spoon, rake)", "Pictures of machines", "Toy wheelbarrow", "Door handle", "Bottle opener", "Matching cards", "Safety posters", "Song charts"]'::jsonb,246) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w3','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'3',3,'teaching',null,'Colours','["Identification of colors", "Primary colors: red, blue, yellow", "Other colors: green, orange, purple, black, white, brown"]'::jsonb,'[]'::jsonb,'["Introduction to Colors:", "The teacher shows objects of different colors one by one", "The teacher names each color clearly: red, blue, yellow, green, orange, purple, black, white, brown", "The teacher explains colors make our world beautiful", "The teacher shows that objects have colors. Primary Colors:", "The teacher introduces red, blue, yellow as primary (main) colors", "The teacher shows objects of each primary color", "The teacher explains these colors can mix to make other colors (simple introduction). Color Activities:", "The teacher conducts color identification games (color hunt in classroom)", "The teacher shows how to sort objects by color", "The teacher demonstrates simple color mixing with paint (red + yellow = orange)", "The teacher provides coloring activities", "The teacher sings color songs"]'::jsonb,'["Learning:", "Pupils observe different colored objects", "Pupils learn color names: red, blue, yellow, green, orange, purple, black, white, brown", "Pupils understand colors are everywhere", "Pupils see that everything has color. Primary Colors:", "Pupils learn red, blue, yellow are primary colors", "Pupils observe objects of each primary color", "Pupils see colors can mix (simple concept). Activities:", "Pupils play color identification games", "Pupils sort objects by color", "Pupils watch color mixing demonstration", "Pupils color pictures with crayons", "Pupils sing color songs enthusiastically"]'::jsonb,'["Colored objects (balls, blocks, toys)", "Colored paper", "Paint (red, blue, yellow)", "Crayons of all colors", "Coloring sheets", "Color flashcards", "Color sorting trays", "Color song charts"]'::jsonb,247) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w4','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'4',4,'teaching',null,'COLOURS (Continued)','["Uses of colors", "Colors in nature", "Recognizing and naming colors", "Favorite colors"]'::jsonb,'[]'::jsonb,'["Uses of Colors:", "The teacher explains colors help us identify things (red apple, yellow banana, green grass)", "The teacher discusses colors make things beautiful (clothes, houses, flowers, paintings)", "The teacher explains some colors have meanings: red (stop), green (go), yellow (caution) - traffic light introduction", "The teacher shows how we use colors in drawings and art. Colors in Nature:", "The teacher shows pictures of nature with colors: blue sky, green trees, brown soil, colorful flowers, rainbow", "The teacher discusses animals have different colors too", "The teacher takes pupils outside to observe colors in nature. Activities:", "The teacher conducts color naming activities with flashcards", "The teacher asks pupils their favorite colors", "The teacher provides creative activities with colors (painting, drawing, crafts)", "The teacher prepares pupils for mid-term assessment"]'::jsonb,'["Uses:", "Pupils understand colors help us know things", "Pupils learn colors make things pretty", "Pupils learn about traffic light colors (simple)", "Pupils use colors in art activities. Nature:", "Pupils observe colors in nature pictures", "Pupils learn about colorful flowers, sky, trees", "Pupils go outside to see colors around them. Activities:", "Pupils name colors when shown flashcards", "Pupils tell teacher their favorite color", "Pupils paint, draw, and create with colors", "Pupils prepare for mid-term test"]'::jsonb,'["Nature pictures", "Pictures of traffic lights", "Colored flashcards", "Painting materials", "Drawing paper", "Crayons", "Craft materials", "Outdoor observation area"]'::jsonb,248) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w5','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'5',5,'midterm_assessment',null,'Mid-term Assessment/tes T','[]'::jsonb,'[]'::jsonb,'["Assessment Activities:", "The teacher administers mid-term assessment", "The teacher tests identification of simple machines", "The teacher assesses knowledge of uses of machines", "The teacher tests color identification (all colors taught)", "The teacher assesses ability to name colors shown", "The teacher evaluates understanding of color uses", "The teacher uses oral questions, picture identification, and practical activities", "The teacher records pupils'' performance"]'::jsonb,'["Assessment Tasks:", "Pupils identify simple machines in pictures and real objects", "Pupils explain what each machine does (with prompts)", "Pupils name all colors shown: red, blue, yellow, green, orange, purple, black, white, brown", "Pupils identify colors of objects presented", "Pupils match colors correctly", "Pupils explain uses of colors (simply)", "Pupils answer oral questions", "Pupils demonstrate learning through practical tasks"]'::jsonb,'["Assessment sheets", "Simple machine pictures", "Real machines", "Colored objects", "Color flashcards", "Matching materials", "Mark book", "Assessment records"]'::jsonb,249) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w6','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'6',6,'midterm_break',null,'Mid-term Break','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,250) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w7','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'7',7,'teaching',null,'Soil','["Meaning of soil", "Where we find soil", "Observation of soil", "Soil supports plants"]'::jsonb,'[]'::jsonb,'["Introduction to Soil:", "The teacher shows samples of soil in containers", "The teacher explains soil is the earth/ground we walk on", "The teacher lets pupils touch and feel soil safely", "The teacher explains soil is found on the ground, in gardens, farms, under our feet. Observation:", "The teacher guides pupils to observe soil: color (usually brown or black), texture (grainy, can be wet or dry)", "The teacher shows that soil can be dug with spade", "The teacher demonstrates how soil holds water. Soil and Plants:", "The teacher reviews plants from first term", "The teacher explains plants grow in soil", "The teacher shows plants growing in soil", "The teacher explains soil gives food and support to plants", "The teacher demonstrates planting in soil"]'::jsonb,'["Learning:", "Pupils observe soil samples", "Pupils understand soil is the ground we walk on", "Pupils touch and feel soil safely", "Pupils learn soil is everywhere on ground. Observation:", "Pupils observe soil''s color and texture", "Pupils see how soil feels (grainy)", "Pupils watch teacher dig soil", "Pupils see soil hold water. Soil and Plants:", "Pupils recall plants from first term", "Pupils understand plants need soil to grow", "Pupils observe plants in soil", "Pupils learn soil feeds and holds plants", "Pupils watch planting demonstration"]'::jsonb,'["Soil samples in containers", "Small spade", "Water", "Potted plants", "Pictures of soil", "Seeds for planting", "Small pots", "Magnifying glass (optional)"]'::jsonb,250) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w8','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'8',8,'teaching',null,'SOIL (Continued)','["Types of soil: clay, loam, sandy", "Simple differences", "Uses of soil"]'::jsonb,'[]'::jsonb,'["Types of Soil:", "The teacher shows three types of soil: clay (sticky, holds water), loam (good for planting, mixture), sandy (grainy, doesn''t hold water well)", "The teacher lets pupils touch and feel each type (if available)", "The teacher explains differences simply: some soil is sticky, some is sandy, some is in between", "The teacher demonstrates how each feels different. Uses of Soil:", "The teacher explains soil is used for: growing plants and food, making bricks, making pottery, building (foundation of houses)", "The teacher shows pictures of soil uses", "The teacher demonstrates simple activity with soil (planting seeds)", "The teacher emphasizes not eating soil or putting in mouth. Activities:", "The teacher conducts soil sorting/observation activities", "The teacher guides pupils in planting activity", "The teacher discusses keeping soil clean (not littering)"]'::jsonb,'["Types:", "Pupils observe three types of soil: clay, loam, sandy", "Pupils touch and feel different soils (carefully)", "Pupils notice some soil is sticky, some is sandy", "Pupils learn soils feel different. Uses:", "Pupils learn soil is for: growing plants, making bricks, making pottery", "Pupils observe pictures of soil uses", "Pupils participate in planting activity", "Pupils learn not to eat soil. Activities:", "Pupils observe and sort soil samples", "Pupils plant seeds with teacher''s help", "Pupils learn to keep soil clean"]'::jsonb,'["Three types of soil samples (clay, loam, sandy)", "Small containers", "Water", "Pictures of soil uses", "Seeds", "Small pots for planting", "Spades", "Pictures of bricks, pottery"]'::jsonb,251) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w9','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'9',9,'teaching',null,'Chemicals Used at Home','["Introduction to chemicals", "Common household chemicals", "Kerosene", "Petrol", "Safety with chemicals"]'::jsonb,'[]'::jsonb,'["Introduction:", "The teacher explains chemicals are special liquids or powders we use at home for different purposes", "The teacher emphasizes chemicals can be dangerous if not used properly", "The teacher shows pictures of household chemicals (not real dangerous ones to pupils)", "The teacher teaches that chemicals are for adults to handle. Kerosene:", "The teacher shows picture of kerosene stove/lamp", "The teacher explains kerosene is used for cooking in stoves and for lighting lamps", "The teacher emphasizes kerosene is not for drinking, very dangerous", "The teacher discusses that adults use kerosene carefully. Petrol:", "The teacher shows pictures of vehicles and generators", "The teacher explains petrol powers cars, motorcycles, generators", "The teacher emphasizes petrol is very dangerous, never touch or drink", "The teacher explains petrol smell is strong. Safety:", "The teacher emphasizes: never touch chemicals, never drink chemicals, tell adults if you see chemicals, keep away from chemical containers", "The teacher discusses dangers of chemicals (can burn, poison, make very sick)", "The teacher teaches to ask adults for help with anything we don''t know"]'::jsonb,'["Learning:", "Pupils understand chemicals are special liquids/powders used at home", "Pupils learn chemicals can be dangerous", "Pupils observe pictures of chemicals (safely)", "Pupils understand only adults use chemicals. Kerosene:", "Pupils see pictures of kerosene stove/lamp", "Pupils learn kerosene is for cooking and lighting", "Pupils understand kerosene is dangerous to drink", "Pupils learn adults must handle it. Petrol:", "Pupils observe pictures of vehicles", "Pupils learn petrol makes cars and generators work", "Pupils understand petrol is very dangerous", "Pupils recognize petrol has strong smell. Safety:", "Pupils learn important safety rules: never touch, never drink chemicals", "Pupils learn to tell adults about chemicals", "Pupils understand dangers of chemicals", "Pupils learn to ask adults for help"]'::jsonb,'["Pictures of kerosene stove/lamp", "Pictures of vehicles and generators", "Chemical safety posters", "Flashcards", "Safety warning signs", "Story book about safety"]'::jsonb,252) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w10','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'10',10,'teaching',null,'Chemicals Used at Home (Continued)','["Detergent and soap", "Disinfectants and antiseptics", "Pesticides", "Safety rules review"]'::jsonb,'[]'::jsonb,'["Detergent and Soap:", "The teacher shows pictures or containers (closed) of detergent and soap", "The teacher explains detergent is for washing clothes and dishes", "The teacher explains soap is for bathing and washing hands", "The teacher demonstrates hand washing with soap (practical, safe activity)", "The teacher emphasizes we use soap every day for cleanliness. Disinfectants and Antiseptics:", "The teacher explains (simply) that disinfectants kill germs on floors and surfaces", "The teacher explains antiseptics kill germs on our skin (like on cuts)", "The teacher shows pictures of cleaning and first aid", "The teacher emphasizes these are also chemicals, only adults use them. Pesticides:", "The teacher explains pesticides kill insects and pests that harm us or plants", "The teacher shows pictures of pest control", "The teacher emphasizes pesticides are dangerous, never touch. Safety Review:", "The teacher reviews all chemical safety rules", "The teacher emphasizes: chemicals help us but can harm us if used wrongly", "The teacher teaches always ask adults, never put chemicals in mouth, keep chemicals away from eyes", "The teacher prepares pupils for revision week"]'::jsonb,'["Detergent and Soap:", "Pupils observe pictures of detergent and soap", "Pupils learn detergent washes clothes and dishes", "Pupils learn soap is for bathing and hand washing", "Pupils practice washing hands with soap properly", "Pupils understand soap keeps us clean. Disinfectants and Antiseptics:", "Pupils learn disinfectants clean and kill germs", "Pupils understand antiseptics are for cuts (first aid)", "Pupils observe cleaning and first aid pictures", "Pupils remember only adults use these. Pesticides:", "Pupils learn pesticides kill harmful insects", "Pupils see pest control pictures", "Pupils understand pesticides are very dangerous. Safety:", "Pupils review all safety rules about chemicals", "Pupils understand chemicals help but can harm", "Pupils remember: ask adults, never drink chemicals, keep away from eyes and mouth", "Pupils prepare for revision"]'::jsonb,'["Pictures of detergent, soap, disinfectants", "Real soap for hand washing demonstration", "Pictures of cleaning", "First aid pictures", "Pest control pictures", "Safety posters", "Hand washing station"]'::jsonb,254) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w11','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'11',11,'revision',null,'REVISION OF THIRD TERM & YEAR''S WORK All topics from three terms','[]'::jsonb,'[]'::jsonb,'["Comprehensive Year-End Revision:", "The teacher systematically reviews Third Term: simple machines (identification, uses), colors (all colors, uses), soil (types, uses), chemicals (kerosene, petrol, soap, safety). First Term Review:", "The teacher briefly reviews First Term: plants, fruits, animals, domestic animals, body parts (head, mouth, teeth, lips, tongue). Second Term Review:", "The teacher briefly reviews Second Term: five senses (eyes, ears, nose, tongue, skin), air (uses, transportation), water (clean/dirty, sources, uses, float/sink). Comprehensive Activities:", "The teacher uses games, songs, demonstrations, and hands-on activities for fun revision", "The teacher conducts comprehensive mock examination covering all three terms", "The teacher identifies areas needing extra support", "The teacher builds strong confidence for final examination", "The teacher celebrates year-long science learning journey"]'::jsonb,'["Third Term Revision:", "Pupils identify simple machines and their uses", "Pupils name all colors learned", "Pupils explain types and uses of soil", "Pupils remember chemical safety rules. First Term Review:", "Pupils recall plants, fruits, animals, body parts from first term. Second Term Review:", "Pupils recall five senses, air, and water topics from second term. Activities:", "Pupils participate enthusiastically in all revision games and activities", "Pupils complete comprehensive mock examination", "Pupils ask questions about difficult areas", "Pupils demonstrate readiness for final examination", "Pupils celebrate their amazing science learning!"]'::jsonb,'["All year''s materials", "Plant samples", "Fruit pictures", "Animal pictures", "Body parts charts", "Five senses materials", "Balloons (air)", "Water samples", "Simple machines", "Colored objects", "Soil samples", "Chemical safety posters", "Comprehensiv e revision worksheets", "Mock examination papers", "Celebration materials"]'::jsonb,256) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w12','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'12',12,'examination',null,'End of Year Examination','[]'::jsonb,'[]'::jsonb,'["Final Examination Administration:", "The teacher administers comprehensive end-of-year pre-science examination. First Term Topics:", "The teacher tests: plant identification, parts, fruits, animal knowledge, domestic animals, body parts (head, mouth, teeth, lips, tongue). Second Term Topics:", "The teacher tests: five senses identification and uses, air properties and uses, air transportation, water (clean/dirty, sources, uses), floating and sinking. Third Term Topics:", "The teacher tests: simple machines identification and uses, color identification and naming, soil types and uses, household chemicals and safety. Assessment Methods:", "The teacher uses oral questions, picture identification, practical demonstrations, and simple written tasks (matching, coloring)", "The teacher observes pupils'' responses, understanding, and participation", "The teacher marks examination thoroughly", "The teacher prepares comprehensive end-of-year report cards with detailed comments"]'::jsonb,'["Final Examination Tasks: First Term:", "Pupils identify plants, fruits, animals, domestic animals, body parts. Second Term:", "Pupils identify five senses and their uses", "Pupils answer questions about air and water", "Pupils identify floating and sinking objects. Third Term:", "Pupils identify simple machines and explain their uses", "Pupils name all colors shown", "Pupils explain types and uses of soil", "Pupils demonstrate knowledge of chemical safety. Performance:", "Pupils answer all oral questions", "Pupils complete practical demonstrations", "Pupils show complete understanding of Nursery 1 Pre-Science topics", "Pupils demonstrate year-long learning and growth"]'::jsonb,'["Comprehensiv e examination papers", "All pictures: plants, fruits, animals, body parts, senses, machines, colors", "Real samples: plants, fruits, soil, simple machines", "Colored objects", "Water and floating objects", "Assessment sheets", "Mark book", "Report cards"]'::jsonb,257) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-pre-science-t3-w13','ng-scheme-2025-preprimary-primary','N1','pre-science',3,'13',13,'closing',null,'Closing, Promotion & Graduation Activities','[]'::jsonb,'[]'::jsonb,'["Year-End Closing:", "The teacher returns marked examination scripts with detailed feedback and encouragement", "The teacher discusses individual year-long performance and growth", "The teacher celebrates remarkable pre-science achievements!", "The teacher awards certificates and prizes for science excellence", "The teacher distributes comprehensive end-of-year report cards", "The teacher provides holiday activities (observe nature, practice safety)", "The teacher prepares pupils for promotion to Nursery", "The teacher conducts science showcase/graduation ceremony where pupils demonstrate what they learned", "The teacher thanks pupils for wonderful year of discovery and learning", "The teacher encourages continued curiosity about the world around them", "The teacher celebrates pupils'' journey through plants, animals, body, senses, air, water, machines, colors, soil, and safety!"]'::jsonb,'["Year-End Closing:", "Pupils receive marked work and comprehensive report cards", "Pupils listen to year-long performance review with pride", "Pupils celebrate their amazing pre-science learning journey!", "Pupils receive certificates and awards for achievements", "Pupils get holiday observation and safety activities", "Pupils prepare excitedly for promotion to Nursery", "Pupils participate in science showcase, demonstrating their knowledge to parents", "Pupils say goodbye with confidence and pride in their science knowledge", "Pupils look forward to continued learning in Nursery", "Pupils celebrate learning about: living things, senses, elements, machines, colors, soil, and safety!"]'::jsonb,'["Report cards", "Marked examination scripts", "Certificates", "Science achievement awards", "Graduation materials", "Holiday activity workbooks", "Science showcase displays", "All learning materials from the year", "Celebration decorations", "Parent feedback forms", "\"I Love", "Science!\" badges"]'::jsonb,259) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w1','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'1',1,'teaching',null,'Self- Awareness','["Talking about self", "Knowing my name", "Knowing my age", "I am special"]'::jsonb,'[]'::jsonb,'["Introduction to Self:", "The teacher creates a welcoming environment and helps each child feel special", "The teacher asks pupils to say their names one by one", "The teacher teaches pupils to introduce themselves: \"My name is...\"", "The teacher helps pupils understand they are unique and special. Personal Information:", "The teacher asks pupils how old they are and helps them show with fingers", "The teacher discusses things that make each pupil special (hair, smile, talents)", "The teacher uses mirror activities for self-recognition", "The teacher takes individual photos of pupils (if permitted). Activities:", "The teacher sings \"What''s Your Name?\" song", "The teacher plays name games and recognition activities", "The teacher guides pupils to draw themselves", "The teacher creates \"All About Me\" displays"]'::jsonb,'["Self-Introduction:", "Pupils say their names when called", "Pupils practice saying \"My name is...\"", "Pupils understand they are special and unique", "Pupils listen to classmates'' names. Personal Information:", "Pupils show their age with fingers", "Pupils talk about what makes them special", "Pupils look at themselves in mirrors", "Pupils have their photos taken (if permitted). Activities:", "Pupils sing name songs", "Pupils participate in name recognition games", "Pupils draw pictures of themselves", "Pupils share about themselves"]'::jsonb,'["Mirrors", "Name tags", "Photos of pupils", "Drawing paper", "Crayons", "Name game materials", "Song charts", "\"All About", "Me\" worksheets", "Display board"]'::jsonb,260) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w2','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'2',2,'teaching',null,'Simple Courtesy: Greetings','["Greeting with appropriate courtesy", "Good morning, Good afternoon, Good evening", "Hello and Hi", "Importance of greetings"]'::jsonb,'[]'::jsonb,'["Teaching Greetings:", "The teacher demonstrates proper greetings with a smile", "The teacher teaches time-appropriate greetings: \"Good morning\" (before 12pm), \"Good afternoon\" (after 12pm), \"Good evening\" (after 6pm)", "The teacher explains \"Hello\" and \"Hi\" can be used anytime", "The teacher emphasizes greeting with a smile and eye contact. Practice:", "The teacher role-plays greeting scenarios with puppets", "The teacher practices greetings with each pupil individually", "The teacher demonstrates greeting elders with respect (adding \"sir/ma\")", "The teacher explains we greet teachers, parents, friends, visitors. Importance:", "The teacher explains greetings show we are friendly and respectful", "The teacher discusses how greetings make people happy", "The teacher encourages pupils to greet everyone at school", "The teacher sings greeting songs"]'::jsonb,'["Learning Greetings:", "Pupils watch greeting demonstrations", "Pupils learn \"Good morning,\" \"Good afternoon,\" \"Good evening\"", "Pupils practice saying \"Hello\" and \"Hi\"", "Pupils greet with smiles. Practice:", "Pupils watch role-play demonstrations", "Pupils practice greeting teacher and classmates", "Pupils learn to greet elders respectfully", "Pupils understand they should greet everyone. Understanding:", "Pupils understand greetings are important", "Pupils see how greetings make people smile", "Pupils greet teachers and friends at school", "Pupils sing greeting songs happily"]'::jsonb,'["Puppets", "Role-play materials", "Pictures of people greeting", "Chart showing different greetings", "Time of day pictures", "Song charts", "Flashcards"]'::jsonb,261) on conflict (id) do nothing;
insert into curriculum_topics values ('N1-social-habits-t1-w3','ng-scheme-2025-preprimary-primary','N1','social-habits',1,'3',3,'teaching',null,'Simple Courtesy: Saying "Thank You"','["When to say \"Thank you\"", "Why we say \"Thank you\"", "Being grateful", "Appreciation"]'::jsonb,'[]'::jsonb,'["Teaching \"Thank You\":", "The teacher explains \"Thank you\" is a polite way to show we appreciate something", "The teacher demonstrates saying \"Thank you\" when receiving something", "The teacher lists situations: when someone gives us something, helps us, does something nice, shares with us", "The teacher emphasizes saying it with a smile. When to Say Thank You:", "The teacher gives examples: receiving a gift, getting help, being served food, someone opens door for you, teacher helps you", "The teacher role-plays various \"thank you\" scenarios", "The teacher demonstrates \"Thank you very much\" for extra politeness", "The teacher introduces \"You''re welcome\" as response. Gratitude:", "The teacher discusses being thankful for what we have", "The teacher explains gratitude makes us and others happy", "The teacher practices \"thank you\" with real classroom situations", "The teacher reads stories about saying thank you"]'::jsonb,'["Learning \"Thank You\":", "Pupils understand \"Thank you\" shows appreciation", "Pupils watch teacher demonstrate \"Thank you\"", "Pupils learn when to say \"Thank you\"", "Pupils say it with smiles. Practice:", "Pupils identify situations needing \"Thank you\"", "Pupils watch and participate in role-plays", "Pupils learn \"Thank you very much\"", "Pupils learn to respond \"You''re welcome\" Understanding:", "Pupils feel grateful for things they have", "Pupils understand gratitude makes everyone happy", "Pupils practice saying \"Thank you\" in class", "Pupils listen to thank you stories"]'::jsonb,'["Role-play props", "Gift boxes (empty)", "Story books about gratitude", "Thank you cards", "Pictures of thank you scenarios", "Puppets", "Chart with \"Thank you\" phrases"]'::jsonb,262) on conflict (id) do nothing;
